import type { ExtensionAPI } from "@earendil-works/pi-coding-agent";
import { Type } from "typebox";
import { execFile } from "node:child_process";

type Cb = (err: { code?: number } | null, stdout: string, stderr: string) => void;

function run(cmd: string, args: string[], timeoutMs = 15000): Promise<{ ok: boolean; stdout: string; stderr: string }> {
  return new Promise((resolve) => {
    execFile(
      cmd,
      args,
      { timeout: timeoutMs, maxBuffer: 8 * 1024 * 1024, encoding: "utf8" },
      (err, stdout, stderr) => {
        // fd/rg/locate exit 1 when there are simply no matches — treat as ok.
        const code = err && typeof (err as { code?: unknown }).code === "number" ? (err as { code?: number }).code : err ? -1 : 0;
        resolve({ ok: code <= 1 || code === 0, stdout: stdout ?? "", stderr: stderr ?? "" });
      },
    );
  });
}

async function which(cmd: string): Promise<boolean> {
  const r = await run("sh", ["-c", `command -v ${cmd}`], 3000);
  return r.stdout.trim().length > 0;
}

function trimLines(out: string, limit: number): string {
  const lines = out.split("\n").filter((l) => l.trim().length > 0);
  if (lines.length <= limit) return lines.join("\n");
  return lines.slice(0, limit).join("\n") + `\n... (truncated, ${lines.length} total matches)`;
}

export default function (pi: ExtensionAPI) {
  pi.registerTool({
    name: "ff_files",
    label: "FF Files",
    description:
      "Fast filename search. Uses `locate` for global searches (whole filesystem index) and falls back to `fd` if locate is unavailable or returns nothing. " +
      "Pass `root` to scope the search to a directory (always uses `fd` for scoped searches, which also avoids locate's stale DB). " +
      "Prefer this over `find`/`ls` for locating files by name.",
    parameters: Type.Object({
      query: Type.String({ description: "Filename pattern (substring/glob). Example: 'config.yaml'" }),
      root: Type.Optional(
        Type.String({ description: "Optional directory to restrict the search to. When set, `fd` is used instead of locate." }),
      ),
      limit: Type.Optional(Type.Number({ description: "Max results to return (default 50)" })),
    }),
    async execute(_id, params) {
      const limit = params.limit ?? 50;
      const query = params.query.trim();

      // Scoped search: always fd (locate DB is stale and directory-scoped anyway)
      if (params.root) {
        if (await which("fd")) {
          const r = await run("fd", ["-t", "f", "--hidden", "--max-results", String(limit + 50), query, params.root]);
          return { content: [{ type: "text", text: r.stdout ? trimLines(r.stdout, limit) : "No files found." }] };
        }
      }

      // Global search: prefer locate, fall back to fd
      if (!params.root && (await which("locate"))) {
        const r = await run("locate", [query], 10000);
        if (r.stdout.trim()) {
          const lower = query.toLowerCase();
          const filtered = r.stdout.split("\n").filter((l) => l.toLowerCase().includes(lower));
          return { content: [{ type: "text", text: trimLines(filtered.join("\n"), limit) }] };
        }
      }

      if (await which("fd")) {
        const home = process.env.HOME ?? "~";
        const r = await run("fd", ["-t", "f", "--hidden", "--max-results", String(limit + 50), "--no-require-git", query, params.root ?? home], 30000);
        return { content: [{ type: "text", text: r.stdout ? trimLines(r.stdout, limit) : "No files found." }] };
      }

      return { content: [{ type: "text", text: "Error: neither locate nor fd is available." }] };
    },
  });

  pi.registerTool({
    name: "ff_grep",
    label: "FF Grep",
    description:
      "Fast content search using `rg` (ripgrep). Pattern is a regex. Respects .gitignore by default. " +
      "Prefer this over `grep` for searching file contents.",
    parameters: Type.Object({
      pattern: Type.String({ description: "Regex pattern to search for in file contents" }),
      root: Type.Optional(Type.String({ description: "Directory to search in (default: current working directory)" })),
      glob: Type.Optional(Type.String({ description: "File glob filter, e.g. '*.py' or 'src/**'" })),
      caseSensitive: Type.Optional(Type.Boolean({ description: "Force case-sensitive matching (default: smart-case)" })),
      context: Type.Optional(Type.Number({ description: "Context lines before/after each match (default 0)" })),
      limit: Type.Optional(Type.Number({ description: "Max match count to return (default 100)" })),
    }),
    async execute(_id, params) {
      if (!(await which("rg"))) {
        return { content: [{ type: "text", text: "Error: rg (ripgrep) is not installed." }] };
      }
      const limit = params.limit ?? 100;
      const args = ["--max-count", String(limit * 4), "--max-columns", "2000"];
      if (params.caseSensitive) args.push("--case-sensitive");
      else args.push("--smart-case");
      if (params.context && params.context > 0) args.push("-C", String(Math.min(params.context, 10)));
      if (params.glob) args.push("--glob", params.glob);
      args.push("--", params.pattern, params.root ?? ".");
      const r = await run("rg", args, 30000);
      const out = r.stdout.trim();
      if (!out) return { content: [{ type: "text", text: "No matches found." }] };
      return { content: [{ type: "text", text: trimLines(out, limit) }] };
    },
  });
}
